/**
 * Brand images are shipped inside the bundle as data URIs, so they load without
 * external requests and keep working under a strict Content Security Policy.
 *
 * To regenerate after changing a source asset:
 * `base64 -i assets/<file>.png` and prepend `data:image/png;base64,`.
 */
export const IMG = {
    TON: 'data:image/png;base64,',
    TG: 'data:image/png;base64,',
    WALLET_CONNECT:
        'https://raw.githubusercontent.com/ton-connect/sdk/main/assets/walletconnect-icon-288.png'
};
